export function LockedAccount({
  heading = "{{heading}}",
  reason = "{{reason}}",
  retryTime = "{{retryTime}}",
  showResetLink = {{showResetLink}},
}) {
  return (
    <div role="alert" style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FBEAEA", width: 300, padding: 20, borderRadius: 14, boxSizing: "border-box", border: "1.5px solid #D64545", textAlign: "center" }}>
      <span aria-hidden="true" style={{ display: "inline-flex", color: "#D64545", marginBottom: 8 }}>
        <svg width="24" height="24" viewBox="0 0 24 24"><rect x="5" y="11" width="14" height="9" rx="2" fill="none" stroke="currentColor" strokeWidth="1.6" /><path d="M8 11V8a4 4 0 0 1 8 0v3" fill="none" stroke="currentColor" strokeWidth="1.6" /></svg>
      </span>
      <h3 style={{ margin: "0 0 8px", fontSize: 16 }}>{heading}</h3>
      <p style={{ margin: "0 0 10px", fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".03em", color: "#a32020" }}>Reason: {reason}</p>
      <p style={{ margin: "0 0 16px", fontSize: 13, color: "#241430cc" }}>Try again in <strong>{retryTime}</strong>, or reset your password to regain access now.</p>
      {showResetLink && <button type="button" style={{ width: "100%", padding: 10, borderRadius: 8, border: "none", background: "#D64545", color: "#FAF7F2", fontWeight: 700, cursor: "pointer" }}>Reset password</button>}
    </div>
  );
}
